<?= $this->extend('layouts/customer') ?><?= $this->section('content') ?><div class="row g-5"><div class="col-lg-6"><?php if($images): ?><div class="row g-2"><?php foreach($images as $i=>$image): ?><div class="<?= $i===0?'col-12':'col-4' ?>"><img class="img-fluid rounded product-image w-100" src="<?= base_url($image['image_path']) ?>" alt="<?= esc($image['alt_text']?:$product['name']) ?>"></div><?php endforeach ?></div><?php elseif($product['main_image']): ?><img class="img-fluid rounded" src="<?= base_url($product['main_image']) ?>" alt="<?= esc($product['name']) ?>"><?php endif ?></div><div class="col-lg-6"><div class="text-muted mb-2"><?= esc($product['category_name']??'') ?></div><h1><?= esc($product['name']) ?></h1><div class="fs-3 fw-bold text-success mb-3">৳<?= number_format($pricing->effectivePrice($product),2) ?></div><?php if($variants): ?><label class="form-label">Choose an option</label><select class="form-select mb-3"><?php foreach($variants as $v): ?><option><?= esc($v['variant_name']) ?> — ৳<?= number_format($pricing->effectivePrice($v),2) ?> — <?= ucwords(str_replace('_',' ',$inventory->stockStatus($v['stock_quantity'],$v['low_stock_threshold']))) ?></option><?php endforeach ?></select><?php else: ?><?php $state=$inventory->stockStatus($product['stock_quantity'],$product['low_stock_threshold']); ?><span class="badge text-bg-<?= $state==='in_stock'?'success':($state==='low_stock'?'warning':'danger') ?> mb-3"><?= ucwords(str_replace('_',' ',$state)) ?></span><?php endif ?><p><?= esc($product['short_description']) ?></p><button class="btn btn-secondary" disabled>Cart coming in next phase</button></div></div><div class="card p-4 mt-5"><h2 class="h4">Description</h2><div><?= nl2br(esc((string)$product['description'])) ?></div></div><?= $this->endSection() ?>
